package com.aerial;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;

public class AerialOverlay extends Overlay
{
	Client client;

	AerialPlugin plugin;

	AerialConfig config;

	static final int[] distances = new int[] {2, 4, 5, 7, 9};

	static final WorldArea ignoreArea = new WorldArea(1360, 3627, 16, 32, 0);

	@Inject
	public AerialOverlay(Client client, AerialPlugin plugin, AerialConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		renderRadii(graphics);
		renderIdleTimer(graphics);

		return null;
	}

	private void renderRadii(Graphics2D graphics)
	{
		if (!config.drawRadius()) {
			return;
		}

		if (!plugin.isGloveEquipped()) {
			return;
		}

		WorldPoint center = client.getLocalPlayer().getWorldLocation();
		for (int dist : distances) {
			square(center, graphics, dist);
		}
	}

	private void renderIdleTimer(Graphics2D graphics)
	{
		if (config.idleTimerRenderLoc() == TimerRenderLocation.NONE) {
			return;
		}

		// No active bird projectiles to track
		if (plugin.getPointToEndTick().isEmpty())
		{
			return;
		}

		// No start tick for projectile tracked
		if (plugin.getTimerStartTick() < 0)
		{
			return;
		}

		LocalPoint pLocPoint = client.getLocalPlayer().getLocalLocation();
		int plane = client.getLocalPlayer().getWorldView().getPlane();
		if (pLocPoint == null)
		{
			return;
		}
		int clientTick = client.getTickCount();
		float percent = (float) (clientTick - plugin.getTimerStartTick()) / (plugin.getTimerCompleteTick() - plugin.getTimerStartTick() + 1);

		Point point = null;
		switch (config.idleTimerRenderLoc()) {
			case POINTER:
				point = client.getMouseCanvasPosition();
				break;
			case PLAYER:
				point = Perspective.localToCanvas(client, pLocPoint, plane);
				break;
		}
		if (point == null || percent > 1.0f)
		{
			return;
		}

		Color fillColor = percent < 1.0f ? Color.YELLOW : Color.GREEN;
		ProgressPieComponent pie = new ProgressPieComponent();
		pie.setPosition(point);
		pie.setBorderColor(fillColor);
		pie.setFill(fillColor);
		pie.setProgress(percent);
		pie.render(graphics);
	}

	private void square(WorldPoint center, Graphics2D graphics, int dist)
	{
		int cx = center.getX();
		int cy = center.getY();

		//top side
		for (int i = -dist; i <= dist; i++) {
			renderWorldPointBorders(graphics, new WorldPoint(cx + i, cy + dist, center.getPlane()), true, false, false, false);
		}

		//bottom side
		for (int i = -dist; i <= dist; i++) {
			renderWorldPointBorders(graphics, new WorldPoint(cx + i, cy - dist, center.getPlane()), false, false, true, false);
		}

		//left side
		for (int i = -dist; i <= dist; i++) {
			renderWorldPointBorders(graphics, new WorldPoint(cx - dist, cy - i, center.getPlane()), false, false, false, true);
		}

		//right side
		for (int i = -dist; i <= dist; i++) {
			renderWorldPointBorders(graphics, new WorldPoint(cx + dist, cy + i, center.getPlane()), false, true, false, false);
		}

	}

	private void renderWorldPointBorders(Graphics2D graphics, WorldPoint worldPoint, boolean topBorder, boolean rightBorder, boolean bottomBorder, boolean leftBorder)
	{
		if (ignoreArea.contains2D(worldPoint)) {
			return;
		}

		LocalPoint localPoint = LocalPoint.fromWorld(client, worldPoint);

		if (localPoint == null)
		{
			return;
		}

		int plane = worldPoint.getPlane();

		graphics.setColor(config.borderColor());
		graphics.setStroke(new BasicStroke(config.borderWidth()));

		if (topBorder)
		{
			Point canvasPointA = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() - 64, localPoint.getY() + 64, localPoint.getWorldView()), plane);

			if (canvasPointA != null)
			{
				int x1 = canvasPointA.getX();
				int y1 = canvasPointA.getY();

				Point canvasPointB = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() + 64, localPoint.getY() + 64, localPoint.getWorldView()), plane);

				if (canvasPointB != null)
				{
					int x2 = canvasPointB.getX();
					int y2 = canvasPointB.getY();

					graphics.drawLine(x1, y1, x2, y2);
				}
			}
		}

		if (rightBorder)
		{
			Point canvasPointA = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() + 64, localPoint.getY() - 64, localPoint.getWorldView()), plane);

			if (canvasPointA != null)
			{
				int x1 = canvasPointA.getX();
				int y1 = canvasPointA.getY();

				Point canvasPointB = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() + 64, localPoint.getY() + 64, localPoint.getWorldView()), plane);

				if (canvasPointB != null)
				{
					int x2 = canvasPointB.getX();
					int y2 = canvasPointB.getY();

					graphics.drawLine(x1, y1, x2, y2);
				}
			}
		}

		if (bottomBorder)
		{
			Point canvasPointA = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() - 64, localPoint.getY() - 64, localPoint.getWorldView()), plane);

			if (canvasPointA != null)
			{
				int x1 = canvasPointA.getX();
				int y1 = canvasPointA.getY();

				Point canvasPointB = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() + 64, localPoint.getY() - 64, localPoint.getWorldView()), plane);

				if (canvasPointB != null)
				{
					int x2 = canvasPointB.getX();
					int y2 = canvasPointB.getY();

					graphics.drawLine(x1, y1, x2, y2);
				}
			}
		}

		if (leftBorder)
		{
			Point canvasPointA = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() - 64, localPoint.getY() - 64, localPoint.getWorldView()), plane);

			if (canvasPointA != null)
			{
				int x1 = canvasPointA.getX();
				int y1 = canvasPointA.getY();

				Point canvasPointB = Perspective.localToCanvas(client, new LocalPoint(localPoint.getX() - 64, localPoint.getY() + 64, localPoint.getWorldView()), plane);

				if (canvasPointB != null)
				{
					int x2 = canvasPointB.getX();
					int y2 = canvasPointB.getY();

					graphics.drawLine(x1, y1, x2, y2);
				}
			}
		}
	}
}

package com.aerial;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("aerial-fishing")
public interface AerialConfig extends Config
{
	@ConfigItem(
		position = 0,
		keyName = "idleSound",
		name = "Play Idle Sound",
		description = "Plays a sound when you can click another spot."
	)
	default boolean idleSound()
	{
		return false;
	}

	@ConfigItem(
		position = 1,
		keyName = "warningSound",
		name = "Play Pre-Idle Sound",
		description = "Plays a sound one tick before you can click another spot."
	)
	default boolean warningSound()
	{
		return false;
	}

	@ConfigItem(
		position = 2,
		keyName = "idleTimerRenderLoc",
		name = "Time-To-Idle Timer Location",
		description = "Configure where to render the timer overlay for Time-To-Idle."
	)
	default TimerRenderLocation idleTimerRenderLoc()
	{
		return TimerRenderLocation.PLAYER;
	}

	@ConfigItem(
		position = 3,
		keyName = "drawBorder",
		name = "Draw Distance Squares",
		description = "Toggle overlay to help spot closer fishing spots."
	)
	default boolean drawRadius()
	{
		return true;
	}

	@ConfigItem(
		position = 4,
		keyName = "borderColor",
		name = "Border color",
		description = "Color of the overlay's border."
	)
	@Alpha
	default Color borderColor()
	{
		return new Color(0x7AFFFF00, true);
	}

	@ConfigItem(
		position = 5,
		keyName = "borderWidth",
		name = "Border width",
		description = "Width of the overlay's border."
	)
	@Range(
		min = 1
	)
	default int borderWidth()
	{
		return 1;
	}
}

package com.aerial;

public enum TimerRenderLocation {
    POINTER,
    PLAYER,
    NONE;
}

package com.aerial;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import javax.inject.Inject;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Projectile;
import net.runelite.api.SoundEffectID;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.SpotanimID;
import net.runelite.api.kit.KitType;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Aerial Fishing"
)
public class AerialPlugin extends Plugin
{
	private static final int FRENZIED_DURATION = 3;
	public static Map<Integer, Integer> distToTicks = null;

	@Inject
	private Client client;

	@Inject
	private AerialConfig config;

	@Inject
	private AerialOverlay aerialOverlay;

	@Inject
	private OverlayManager overlayManager;

	@Getter
	private int timerCompleteTick = -1;
	@Getter
	private int timerStartTick = -1;

	private List<WorldPoint> frenziedPoints = new ArrayList<>();

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(aerialOverlay);
		distToTicks = new HashMap<>();
		distToTicks.put(1, 0);
		distToTicks.put(2, 0);
		distToTicks.put(3, 1);
		distToTicks.put(4, 1);
		distToTicks.put(5, 2);
		distToTicks.put(6, 3);
		distToTicks.put(7, 3);
		distToTicks.put(8, 4);
		distToTicks.put(9, 4);
		distToTicks.put(10, 5);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(aerialOverlay);
		distToTicks = null;
		frenziedPoints.clear();
		pointToEndTick.clear();
	}

	@Getter
	private final Map<Integer, Integer> pointToEndTick = new HashMap<>();

	@Subscribe
	public void onGameTick(GameTick event) {
		if (!isGloveEquipped()) {
			resetState();
			return;
		}

		for (Projectile p : client.getProjectiles()) {
			if (p.getId() != SpotanimID.AERIAL_FISHING_TRAVEL) {
				continue;
			}
			if (p.getTargetActor() == null || !Objects.equals(p.getTargetActor().getName(), client.getLocalPlayer().getName())) {
				continue;
			}

			int hash = p.getStartCycle();
			if (pointToEndTick.containsKey(hash)) {
				continue;
			}

			WorldPoint point = p.getSourcePoint();
			int distanceToTicks;
			if (frenziedPoints.contains(point)) {
				distanceToTicks = FRENZIED_DURATION - 1; // duration is offset by 1 tick
			} else {
				int distance = point.distanceTo2D(p.getTargetPoint());
				distanceToTicks = distToTicks.getOrDefault(distance, -1);
			}

			timerCompleteTick = client.getTickCount() + distanceToTicks;
			timerStartTick = client.getTickCount();
			pointToEndTick.put(hash, timerCompleteTick);
		}


		for(Iterator<Map.Entry<Integer, Integer>> it = pointToEndTick.entrySet().iterator(); it.hasNext(); ) {
			Map.Entry<Integer, Integer> entry = it.next();
			if (client.getTickCount() + 1 == entry.getValue() && config.warningSound()) {
				client.playSoundEffect(SoundEffectID.TOWN_CRIER_BELL_DING);
			}

			if (client.getTickCount() == entry.getValue() && config.idleSound()) {
				client.playSoundEffect(3815);
			}

			if (client.getTickCount() >= entry.getValue() + 6) {
				it.remove();
			}
		}
	}

	@Subscribe
	private void onNpcSpawned(NpcSpawned event)
	{
		if (event.getNpc().getId() == NpcID.FISHING_SPOT_AERIAL_LARGE) {
			WorldPoint swTilePoint = event.getNpc().getWorldLocation();
			int offset = event.getNpc().getComposition().getSize()/2;
			// offset to the center of the npc to match projectile point
			frenziedPoints.add(swTilePoint.dx(offset).dy(offset));
		}
	}

	@Subscribe
	private void onNpcDespawned(NpcDespawned event) {
		if (event.getNpc().getId() == NpcID.FISHING_SPOT_AERIAL_LARGE) {
			WorldPoint swTilePoint = event.getNpc().getWorldLocation();
			int offset = event.getNpc().getComposition().getSize()/2;
			// offset to the center of the npc to match projectile point
			frenziedPoints.remove(swTilePoint.dx(offset).dy(offset));
		}
	}

	public boolean isGloveEquipped()
	{
		int weaponId = client.getLocalPlayer().getPlayerComposition().getEquipmentId(KitType.WEAPON);

		// Whether worn weapon is the aerial fishing glove
        return weaponId == ItemID.AERIAL_FISHING_GLOVES_BIRD || weaponId == ItemID.AERIAL_FISHING_GLOVES_NO_BIRD;
    }

	protected void resetState() {
		pointToEndTick.clear();
		timerCompleteTick = -1;
		timerStartTick = -1;
		frenziedPoints.clear();
	}

	@Provides
	AerialConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AerialConfig.class);
	}
}
